// Target = yesterday in Europe/Warsaw. Mon-Fri are workdays, Sat-Sun are off.
// test_now can be pinned on the "Manual test" trigger to simulate a run time.
const ZONE = 'Europe/Warsaw';
const cfg = $('Config').first().json;
const now = cfg.test_now
  ? DateTime.fromISO(String(cfg.test_now), { zone: ZONE })
  : DateTime.now().setZone(ZONE);
// The schedule fires every day at 9:30, 14:00 and 21:30 (invoice reminders need every day).
// The Everhour check keeps its own rhythm: 9:30 Mon-Sat, 14:00 and 21:30 Tue-Sat.
const ehRun = now.hour < 12 ? now.weekday <= 6 : (now.weekday >= 2 && now.weekday <= 6);
if (!ehRun) return [];
const lockDays = Math.max(1, Number(cfg.LOCK_DAYS) || 2);
const target = now.minus({ days: 1 }).startOf('day');

return [{
  json: {
    now: now.toISO(),
    today: now.toISODate(),
    target: target.toISODate(),
    isWorkday: target.weekday <= 5,
    slot: now.hour < 12 ? 'morning' : (now.hour < 18 ? 'afternoon' : 'evening'),
    oldestEditable: now.minus({ days: lockDays - 1 }).toISODate(),
    from: target.minus({ days: 35 }).toISODate(),
  },
}];

// Decide what to send for the target day and for pending days that got locked.
// Fail-open: if Everhour cannot be read, remind anyway.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
};
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const errText = (res) => {
  if (!res) return 'brak odpowiedzi';
  if (res.error) return String(res.error.message || res.error).slice(0, 200);
  const b = res.body;
  const msg = b && typeof b === 'object' ? (b.message || b.error || JSON.stringify(b)) : String(b ?? '');
  return `HTTP ${res.statusCode ?? '?'}${msg ? ': ' + msg : ''}`.slice(0, 200);
};

const cfg = $('Config').first().json;
const t = $('Compute target day').first().json;
const chatId = String(cfg.TELEGRAM_CHAT_ID ?? '').trim();
if (!chatId) {
  throw new Error('Config: TELEGRAM_CHAT_ID is empty. Send /start to the bot and paste the chat_id into Config.');
}
const MIN = Number(cfg.MIN_HOURS) || 6;
const MAX = Number(cfg.MAX_HOURS) || 10;

// Reminder state (DataTable)
const stateRows = $('Get reminder state').all().map((i) => i.json)
  .filter((r) => r && typeof r.date === 'string' && r.date);
const st = stateRows.find((r) => r.date === t.target) || null;

// Everhour
const meRes = $('Everhour: me (check)').first().json;
const timeRes = $('Everhour: time (check)').first().json;
const meOk = Boolean(meRes && meRes.statusCode === 200 && meRes.body && meRes.body.id);
const ehOk = meOk && Boolean(timeRes && timeRes.statusCode === 200 && Array.isArray(timeRes.body));
const ehError = !meOk ? errText(meRes) : (ehOk ? '' : errText(timeRes));
const records = ehOk ? timeRes.body.filter((r) => r && r.date) : [];
const secondsOn = (iso) => records.filter((r) => r.date === iso).reduce((s, r) => s + (Number(r.time) || 0), 0);
const cfgTask = String(cfg.EVERHOUR_TASK_ID ?? '').trim();
// Main task = most time in the 14 days before the day (one-off HR/meeting entries do not win)
const mainTask = (list, beforeIso) => {
  const since = DateTime.fromISO(beforeIso, { zone: ZONE }).minus({ days: 14 }).toISODate();
  const withTask = list.filter((x) => x.task && x.task.id);
  const recent = withTask.filter((x) => String(x.date) >= since);
  const totals = new Map();
  for (const x of (recent.length ? recent : withTask)) {
    const id = String(x.task.id);
    const e = totals.get(id) || { id, name: x.task.name, sec: 0, last: '' };
    e.sec += Number(x.time) || 0;
    if (String(x.date) > e.last) e.last = String(x.date);
    totals.set(id, e);
  }
  return [...totals.values()].sort((a, b) => b.sec - a.sec || b.last.localeCompare(a.last))[0] || null;
};
const auto = mainTask(records, t.target);
const taskRec = cfgTask ? records.find((r) => r.task && String(r.task.id) === cfgTask) : null;
const taskName = cfgTask ? (taskRec ? taskRec.task.name : cfgTask) : (auto ? auto.name : '');

const out = [];
const DONE = ['logged', 'day_off', 'ok', 'missed'];

// 1) Days still pending that are now outside the edit window
for (const r of stateRows) {
  if (r.status !== 'pending' || r.date >= t.oldestEditable) continue;
  const pings = Number(r.pings) || 0;
  if (r.date < t.from) {
    out.push({ route: 'none', state: { date: r.date, status: 'missed', hours: 0, pings, note: 'stale' } });
    continue;
  }
  if (!ehOk) continue; // verify on a later run
  const sec = secondsOn(r.date);
  if (sec > 0) {
    out.push({ route: 'none', state: { date: r.date, status: 'logged', hours: sec / 3600, pings, note: 'logged outside bot' } });
  } else {
    out.push({
      route: 'plain',
      chatId,
      text: `Everhour: <b>${label(r.date)}</b> został bez godzin, a edycja jest już zablokowana. Poproś administratora Everhoura w firmie o odblokowanie albo dopisanie godzin.`,
      state: { date: r.date, status: 'missed', hours: 0, pings, note: 'locked without entry' },
    });
  }
}

// 2) Target day (yesterday)
if (t.isWorkday && !(st && DONE.includes(st.status))) {
  const pings = st ? Number(st.pings) || 0 : 0;
  const sec = secondsOn(t.target);
  const h = sec / 3600;
  const prefix = t.slot === 'evening' ? 'Ostatnie przypomnienie. ' : (t.slot === 'afternoon' ? 'Przypominam. ' : '');
  const lockLine = t.slot === 'evening' ? 'O północy ten dzień się zablokuje.' : 'Edycja tego dnia działa do dzisiejszej północy.';
  const tag = `\n<code>${t.target}</code>`;
  const day = `<b>${label(t.target)}</b>`;

  if (!ehOk) {
    out.push({
      route: 'button', chatId, buttonText: 'Wolne', buttonData: `off|${t.target}`,
      text: `${prefix}Nie mogę sprawdzić Everhoura (${esc(ehError)}). Upewnij się, że ${day} jest zalogowany. Możesz też odpisać liczbę godzin, spróbuję wpisać.${tag}`,
      state: { date: t.target, status: 'pending', hours: 0, pings: pings + 1, note: 'everhour check failed' },
    });
  } else if (sec === 0) {
    out.push({
      route: 'button', chatId, buttonText: 'Wolne', buttonData: `off|${t.target}`,
      text: `${prefix}Brak godzin w Everhourze za ${day}.\nOdpisz, ile wpisać (np. 8, 7,5 albo 7:30)${taskName ? `, zaloguję na „${esc(taskName)}”` : ''}.\n${lockLine}${tag}`,
      state: { date: t.target, status: 'pending', hours: 0, pings: pings + 1, note: 'missing' },
    });
  } else if (h < MIN || h > MAX) {
    out.push({
      route: 'button', chatId, buttonText: 'OK, zostaw', buttonData: `ok|${t.target}`,
      text: `${prefix}Za ${day} masz w Everhourze ${h < MIN ? 'tylko' : 'aż'} ${fmtH(h)} h.\nJeśli tak ma być, kliknij „OK, zostaw”. Jeśli nie, odpisz łączną liczbę godzin za ten dzień.\n${lockLine}${tag}`,
      state: { date: t.target, status: 'pending', hours: h, pings: pings + 1, note: h < MIN ? 'low' : 'high' },
    });
  } else if (st && st.status === 'pending') {
    out.push({ route: 'none', state: { date: t.target, status: 'logged', hours: h, pings, note: 'logged outside bot' } });
  }
}

return out.map((json) => ({ json }));

// Turn a Telegram update (text message or button press) into an intent.
// Only the chat from Config.TELEGRAM_CHAT_ID is served; others are ignored.
const ZONE = 'Europe/Warsaw';
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const cfg = $('Config').first().json; // Config passes the Telegram update through
const allowed = String(cfg.TELEGRAM_CHAT_ID ?? '').trim();
const msg = cfg.message || null;
const cb = cfg.callback_query || null;
const chat = msg ? msg.chat : (cb && cb.message ? cb.message.chat : null);
if (!chat || chat.id === undefined || chat.id === null) return [];
const chatId = String(chat.id);

const base = {
  chatId,
  isCallback: Boolean(cb),
  callbackId: cb ? String(cb.id) : '',
  intent: 'reply',
  status: '',
  date: '',
  until: '',
  hours: 0,
  seconds: 0,
  comment: '',
  text: '',
};
const reply = (text) => [{ json: { ...base, intent: 'reply', text } }];

if (!allowed) {
  return reply(`Bot działa. Twój chat_id: <code>${chatId}</code>\nWpisz go w node Config (pole TELEGRAM_CHAT_ID) i opublikuj workflow.`);
}
if (chatId !== allowed) return [];

const HELP = [
  'Pilnuję godzin w Everhourze. Rano, po południu i wieczorem sprawdzam poprzedni dzień roboczy (pn–pt) i piszę, jeśli czegoś brakuje.',
  '',
  'Odpowiedź na przypomnienie:',
  '• liczba godzin, np. 8, 7,5, 7:30 albo 7h30 (łącznie za dzień; tekst po liczbie trafia do komentarza)',
  '• 0 albo wolne (też urlop, L4): dzień wolny, koniec przypomnień; tekst po nim trafia do notatki, np. „0 L4”',
  '• ok: zostaw jak jest',
  '',
  'Wolne na kilka dni: „0 do piątku”, „L4 do 16.10”, „wolne do jutra”. Liczę od dziś (w odpowiedzi na przypomnienie od jego dnia) i do tego czasu nie przypominam.',
  'wracam: odwołuje zaplanowane wolne od dziś.',
  'Bez przypomnienia też możesz napisać liczbę albo 0, zapytam: dziś czy wczoraj.',
  '',
  'Komendy:',
  '/status: profil Everhoura, ostatnie 7 dni i zaplanowane wolne',
  '/tydzien: godziny w tym tygodniu („/tydzien poprzedni” = zeszły)',
  '/raport: raport miesięczny z Everhoura, domyślnie za poprzedni miesiąc („/raport bieżący”, „/raport 9”, „/raport wrzesień”, „/raport 2026-09”)',
  'wystawiona: faktura za miesiąc odhaczona. Termin to ostatni dzień roboczy miesiąca: przypominam dzień wcześniej, a od terminu do skutku.',
].join('\n');

const lastIso = (s) => {
  const m = String(s || '').match(/\d{4}-\d{2}-\d{2}/g);
  return m ? m[m.length - 1] : '';
};

// Reports: totals come from Everhour's own report endpoints, the bot only picks the date range
const now0 = DateTime.now().setZone(ZONE);
const MONTH_NAMES = ['styczeń', 'luty', 'marzec', 'kwiecień', 'maj', 'czerwiec', 'lipiec', 'sierpień', 'wrzesień', 'październik', 'listopad', 'grudzień'];
const dm = (d) => `${d.day}.${String(d.month).padStart(2, '0')}`;
const monthReport = (y, m) => {
  const start = DateTime.fromObject({ year: y, month: m, day: 1 }, { zone: ZONE });
  if (!start.isValid) return reply('Nie rozpoznaję miesiąca.');
  if (start > now0) return reply('Ten miesiąc jeszcze się nie zaczął.');
  return [{
    json: {
      ...base, intent: 'report', reportKind: 'month', from: start.toISODate(), to: start.endOf('month').toISODate(),
      period: `${MONTH_NAMES[m - 1]} ${y}`, running: start.hasSame(now0, 'month'),
    },
  }];
};

if (cb) {
  const [kind, date = '', val = ''] = String(cb.data || '').split('|');
  if (kind === 'off') return [{ json: { ...base, intent: 'mark', status: 'day_off', date, comment: val } }];
  if (kind === 'ok') return [{ json: { ...base, intent: 'mark', status: 'ok', date } }];
  if (kind === 'log') {
    const seconds = Number(val);
    if (!(seconds > 0 && seconds <= 16 * 3600)) return reply('Niepoprawna wartość w przycisku.');
    return [{ json: { ...base, intent: 'log', date, seconds, hours: seconds / 3600 } }];
  }
  if (kind === 'cancel') return reply('OK, nic nie wpisuję.');
  if (kind === 'inv') return [{ json: { ...base, intent: 'invoice', invoicePeriod: date } }];
  if (kind === 'rep') {
    const mm = date.match(/^(\d{4})-(\d{2})$/);
    return mm ? monthReport(Number(mm[1]), Number(mm[2])) : reply('Niepoprawny przycisk raportu.');
  }
  return reply('Nie znam tego przycisku.');
}

const text = typeof msg.text === 'string' ? msg.text.trim() : '';
if (!text) return reply('Obsługuję tylko tekst. Odpisz liczbę godzin, np. 8 albo 7:30.');
const replyDate = msg.reply_to_message ? lastIso(msg.reply_to_message.text) : '';
const cmd = text.toLowerCase().replace(/^(\/[^\s@]+)@\w+/, '$1'); // "/raport@bot 9" -> "/raport 9"

if (/^\/(start|help|pomoc)$/.test(cmd)) return reply(HELP);
if (cmd === '/status') return [{ json: { ...base, intent: 'status' } }];

// Monthly invoice issued: "wystawiona", "wystawiłem", "fv wystawiona" (month from the reminder tag if replying)
if (/^(?:faktura\s+|fv\s+)?(?:wystawiona|wystawione|wystawi[lł]em|wystawi[lł]am)[.!]?$/.test(cmd)) {
  const tagged = msg.reply_to_message ? (String(msg.reply_to_message.text || '').match(/faktura (\d{4}-\d{2})/) || [])[1] : '';
  return [{ json: { ...base, intent: 'invoice', invoicePeriod: tagged || '' } }];
}

const weekCmd = cmd.match(/^\/(?:tydzien|tydzień|tydz|week)(?:\s+(.*))?$/);
if (weekCmd) {
  const arg = String(weekCmd[1] || '').trim();
  if (arg && !/^(poprzedni|zesz[lł]y|ubieg[lł]y|-1)$/.test(arg)) return reply('Użyj <code>/tydzien</code> albo <code>/tydzien poprzedni</code>.');
  const start = now0.startOf('week').minus({ weeks: arg ? 1 : 0 });
  const end = start.plus({ days: 6 });
  return [{ json: { ...base, intent: 'report', reportKind: 'week', from: start.toISODate(), to: end.toISODate(), period: `${dm(start)}–${dm(end)}` } }];
}
const monthCmd = cmd.match(/^\/(?:raport|report|miesiac|miesiąc)(?:\s+(.*))?$/);
if (monthCmd) {
  const a = String(monthCmd[1] || '').trim();
  const prev = now0.minus({ months: 1 });
  const guessYear = (mm) => (mm > now0.month ? now0.year - 1 : now0.year);
  let ym = null;
  let mt;
  if (!a || /^(poprzedni|zesz[lł]y|ubieg[lł]y)$/.test(a)) ym = { y: prev.year, m: prev.month };
  else if (/^(bie[zż][aą]cy|ten|teraz|obecny)$/.test(a)) ym = { y: now0.year, m: now0.month };
  else if ((mt = a.match(/^(\d{4})-(\d{1,2})$/))) ym = { y: Number(mt[1]), m: Number(mt[2]) };
  else if ((mt = a.match(/^(\d{1,2})[./-](\d{4})$/))) ym = { y: Number(mt[2]), m: Number(mt[1]) };
  else if ((mt = a.match(/^(\d{1,2})$/))) ym = { y: guessYear(Number(mt[1])), m: Number(mt[1]) };
  else {
    const n = a.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ł/g, 'l');
    const idx = ['sty', 'lut', 'mar', 'kwi', 'maj', 'cze', 'lip', 'sie', 'wrz', 'paz', 'lis', 'gru'].findIndex((pre) => n.startsWith(pre));
    if (idx >= 0) {
      const yy = (n.match(/(\d{4})/) || [])[1];
      ym = { y: yy ? Number(yy) : guessYear(idx + 1), m: idx + 1 };
    }
  }
  if (!ym || !(ym.m >= 1 && ym.m <= 12)) {
    return reply('Nie rozpoznaję miesiąca. Przykłady: <code>/raport</code> (poprzedni), <code>/raport bieżący</code>, <code>/raport 9</code>, <code>/raport wrzesień</code>, <code>/raport 2026-09</code>.');
  }
  return monthReport(ym.y, ym.m);
}
if (/^(wracam|wróciłem|wrocilem|wróciłam|koniec wolnego)$/.test(cmd)) return [{ json: { ...base, intent: 'resume' } }];

const parseHours = (s) => {
  const v = s.replace(/^(\d+),(\d+)/, '$1.$2'); // decimal comma, leading number only
  let m = v.match(/^(\d{1,2}):([0-5]\d)(?:\s+([\s\S]*))?$/);
  if (m) return { hours: Number(m[1]) + Number(m[2]) / 60, comment: m[3] };
  m = v.match(/^(\d{1,2}(?:\.\d+)?)\s*(?:h|godz\.?|godzin[ay]?)\s*(?:(\d{1,2})\s*(?:m|min\.?)?)?(?:\s+([\s\S]*))?$/i);
  if (m) return { hours: Number(m[1]) + (m[2] ? Number(m[2]) / 60 : 0), comment: m[3] };
  m = v.match(/^(\d{2,3})\s*(?:m|min\.?)(?:\s+([\s\S]*))?$/i);
  if (m) return { hours: Number(m[1]) / 60, comment: m[2] };
  m = v.match(/^(\d{1,2}(?:\.\d{1,2})?)(?:\s+([\s\S]*))?$/);
  if (m) return { hours: Number(m[1]), comment: m[2] };
  return null;
};
const OFF_WORD = /^(wolne|urlop|off|l4|chorobowe)(?:\s+([\s\S]*))?$/i;
const isOff = (s) => OFF_WORD.test(s) || (parseHours(s) || {}).hours === 0;

// "do <day>" sets the last day of a day-off range: piątku / pt / jutra / końca tygodnia / 16.10 / 2026-10-16
const now = DateTime.now().setZone(ZONE);
const nextWeekday = (wd) => { let d = now.startOf('day'); while (d.weekday !== wd) d = d.plus({ days: 1 }); return d; };
const WEEKDAYS = [[1, /^(pon|pn)/], [2, /^wt/], [3, /^(sr|śr)/], [4, /^czw/], [5, /^(pi[aą]|pt)/], [6, /^sob/], [7, /^(nd|niedz)/]];
const untilDate = (token) => {
  const t = token.toLowerCase().replace(/\.$/, '');
  if (t === 'jutra') return now.plus({ days: 1 }).startOf('day');
  if (t === 'pojutrza') return now.plus({ days: 2 }).startOf('day');
  if (/^ko[nń]ca\s+tygodnia$/.test(t)) return nextWeekday(5);
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return DateTime.fromObject({ year: Number(m[1]), month: Number(m[2]), day: Number(m[3]) }, { zone: ZONE });
  m = t.match(/^(\d{1,2})[./](\d{1,2})(?:[./](\d{2}|\d{4}))?$/);
  if (m) {
    const year = m[3] ? Number(m[3].length === 2 ? `20${m[3]}` : m[3]) : now.year;
    let d = DateTime.fromObject({ year, month: Number(m[2]), day: Number(m[1]) }, { zone: ZONE });
    if (!m[3] && d.isValid && d < now.startOf('day')) d = d.plus({ years: 1 });
    return d;
  }
  for (const [wd, re] of WEEKDAYS) if (re.test(t)) return nextWeekday(wd);
  return null;
};

let body = text;
let until = '';
const um = text.match(/(?:^|\s)do\s+(ko[nń]ca\s+tygodnia|\d{4}-\d{2}-\d{2}|\d{1,2}[./]\d{1,2}(?:[./]\d{2,4})?|\p{L}+\.?)(?=\s|$)/iu);
if (um) {
  const d = untilDate(um[1]);
  if (d && d.isValid) {
    const rest = `${text.slice(0, um.index)} ${text.slice(um.index + um[0].length)}`.replace(/\s+/g, ' ').trim();
    if (isOff(rest)) {
      body = rest;
      until = d.toISODate();
    } else {
      const ph = parseHours(rest);
      if (ph && ph.hours > 0 && !String(ph.comment || '').trim()) {
        return reply('Godzin nie wpisuję z wyprzedzeniem. Zakres „do …” działa dla wolnego, np. <code>0 do piątku</code> albo <code>L4 do 16.10</code>.');
      }
    }
  }
}

const dayOff = (comment) => [{
  json: { ...base, intent: 'mark', status: 'day_off', date: replyDate, until, comment: String(comment || '').trim().slice(0, 200) },
}];
const offWord = body.match(OFF_WORD);
if (offWord) {
  const tag = { l4: 'L4', urlop: 'urlop', chorobowe: 'chorobowe' }[offWord[1].toLowerCase()] || '';
  return dayOff([tag, String(offWord[2] || '').trim()].filter(Boolean).join(' '));
}
if (/^(ok|okej|okay|zostaw|ok, zostaw)$/.test(cmd)) return [{ json: { ...base, intent: 'mark', status: 'ok', date: replyDate } }];

const p = parseHours(body);
if (!p) {
  return reply('Nie rozumiem. Odpisz liczbę godzin, np. <code>8</code>, <code>7,5</code>, <code>7:30</code> albo <code>7h30</code>. Pomoc: /help');
}
if (p.hours === 0) return dayOff(p.comment); // 0, 0h, 0:00, "0 L4" = day off, nothing goes to Everhour
if (!(p.hours <= 16)) return reply(`${fmtH(p.hours)} h? Maksymalnie 16 h na dzień.`);
const seconds = Math.round(p.hours * 60) * 60;
return [{
  json: { ...base, intent: 'log', date: replyDate, seconds, hours: seconds / 3600, comment: String(p.comment || '').trim().slice(0, 500) },
}];

// Resolve the day an answer refers to and pick the route.
// Date order: button/reply-to tag > newest pending reminder > ask (today/yesterday).
// Day-off ranges ("0 do piątku") start today, or at the reminder's day when replying to it, and never ask.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const label = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
};
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram callback_data max 64 bytes: "off|YYYY-MM-DD|" + 12 code points (<= 4 bytes each)
const cbText = (s) => Array.from(String(s || '').replace(/\|/g, '/').trim()).slice(0, 12).join('');
const workdays = (n) => (n === 1 ? 'dzień roboczy' : (n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 'dni robocze' : 'dni roboczych'));
const MAX_AHEAD_DAYS = 45;

const p = $('Parse update').first().json;
const cfg = $('Config').first().json;
const now = DateTime.now().setZone(ZONE);
const today = now.toISODate();
const yesterday = now.minus({ days: 1 }).toISODate();
const lockDays = Math.max(1, Number(cfg.LOCK_DAYS) || 2);
const oldest = now.minus({ days: lockDays - 1 }).toISODate();
const rows = $('Get pending days').all().map((i) => i.json).filter((r) => r && typeof r.date === 'string' && r.date);
const pending = rows.filter((r) => r.status === 'pending' && r.date >= oldest && r.date <= today)
  .sort((a, b) => b.date.localeCompare(a.date));
const plannedOff = rows.filter((r) => r.status === 'day_off' && r.date >= today && String(r.note || '').startsWith('telegram'))
  .sort((a, b) => a.date.localeCompare(b.date));
const reply = (text) => [{ json: { ...p, route: 'reply', text } }];

if (p.intent === 'reply') return [{ json: { ...p, route: 'reply' } }];
if (p.intent === 'status') {
  return [{ json: { ...p, route: 'status', from: now.minus({ days: 6 }).toISODate(), to: today } }];
}

if (p.intent === 'report') return [{ json: { ...p, route: 'report' } }];
if (p.intent === 'invoice') return [{ json: { ...p, route: 'invoice' } }];

if (p.intent === 'resume') {
  if (!plannedOff.length) return reply('Nie mam zaplanowanego wolnego, przypominam normalnie.');
  const states = plannedOff.map((r) => ({ state: { date: r.date, status: 'cancelled', note: 'telegram: wracam' } }));
  return [{
    json: { ...p, route: 'mark', states, text: `OK, odwołuję wolne: ${plannedOff.map((r) => label(r.date)).join(', ')}. Przypomnienia wracają.` },
  }];
}

if (p.intent === 'mark' && p.status === 'day_off' && p.until) {
  const start = p.date || today;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start) || !/^\d{4}-\d{2}-\d{2}$/.test(p.until)) return reply('Nie rozpoznaję daty.');
  if (p.until < start) return reply(`<b>${label(p.until)}</b> wypada przed <b>${label(start)}</b>. Podaj późniejszy dzień.`);
  const end = DateTime.fromISO(p.until, { zone: ZONE });
  if (end > now.startOf('day').plus({ days: MAX_AHEAD_DAYS })) return reply(`Maksymalnie ${MAX_AHEAD_DAYS} dni naprzód.`);
  const days = [];
  for (let d = DateTime.fromISO(start, { zone: ZONE }); d <= end; d = d.plus({ days: 1 })) {
    if (d.weekday <= 5) days.push(d.toISODate());
  }
  if (!days.length) return reply('W tym zakresie nie ma dni roboczych.');
  const why = p.comment ? ` (${esc(p.comment)})` : '';
  const note = `telegram: ${p.comment ? `${String(p.comment).slice(0, 150)} ` : ''}do ${p.until}`;
  const states = days.map((date) => ({ state: { date, status: 'day_off', note } }));
  const span = days.length === 1
    ? `<b>${label(days[0])}</b>`
    : `od <b>${label(days[0])}</b> do <b>${label(days[days.length - 1])}</b> (${days.length} ${workdays(days.length)})`;
  const open = pending.filter((r) => r.date < start);
  const openLine = open.length
    ? `\n${open.map((r) => `<b>${label(r.date)}</b>`).join(', ')} nadal czeka na odpowiedź (liczba godzin albo 0).`
    : '';
  return [{ json: { ...p, route: 'mark', states, text: `OK, wolne ${span}${why}. Do tego czasu nie przypominam.${openLine}` } }];
}

const ask = (text, todayData, yesterdayData) => [{
  json: {
    ...p,
    route: 'ask',
    text,
    todayLabel: `Dziś, ${label(today)}`,
    todayData,
    yesterdayLabel: `Wczoraj, ${label(yesterday)}`,
    yesterdayData,
  },
}];

let date = p.date;
if (!date && pending.length) date = pending[0].date;
if (!date) {
  if (p.intent === 'log') {
    return ask(`Za który dzień wpisać ${fmtH(p.hours)} h?`, `log|${today}|${p.seconds}`, `log|${yesterday}|${p.seconds}`);
  }
  if (p.intent === 'mark' && p.status === 'day_off') {
    const c = cbText(p.comment);
    return ask('Który dzień oznaczyć jako wolny?', `off|${today}|${c}`, `off|${yesterday}|${c}`);
  }
  return reply('Nie mam otwartego przypomnienia. Odpowiedz bezpośrednio na wiadomość z datą.');
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return reply('Nie rozpoznaję daty w tej wiadomości.');

if (p.intent === 'mark') {
  const why = p.comment ? ` (${esc(p.comment)})` : '';
  const text = p.status === 'day_off'
    ? `OK, <b>${label(date)}</b> to dzień wolny${why}. Nie przypominam.`
    : `OK, zostawiam <b>${label(date)}</b> bez zmian.`;
  const note = p.comment ? `telegram: ${String(p.comment).slice(0, 200)}` : 'telegram';
  return [{ json: { ...p, date, route: 'mark', text, states: [{ state: { date, status: p.status, note } }] } }];
}

// log
if (date < oldest) {
  return reply(`<b>${label(date)}</b> jest już poza oknem edycji w Everhourze. Poproś administratora Everhoura w firmie o odblokowanie albo dopisanie godzin.`);
}
if (date > today) return reply('Nie wpisuję godzin z wyprzedzeniem.');
return [{
  json: { ...p, date, route: 'log', from: DateTime.fromISO(date, { zone: ZONE }).minus({ days: 45 }).toISODate(), to: date },
}];

// Plan the Everhour write so the day total equals the answered value.
// Task: Config.EVERHOUR_TASK_ID, or the task with the most time in the 14 days before the day.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
};
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const errText = (res) => {
  if (!res) return 'brak odpowiedzi';
  if (res.error) return String(res.error.message || res.error).slice(0, 200);
  const b = res.body;
  const msg = b && typeof b === 'object' ? (b.message || b.error || JSON.stringify(b)) : String(b ?? '');
  return `HTTP ${res.statusCode ?? '?'}${msg ? ': ' + msg : ''}`.slice(0, 200);
};

const r = $('Resolve action').first().json;
const cfg = $('Config').first().json;
const me = $('Everhour: me (log)').first().json;
const tr = $('Everhour: time (log)').first().json;
const reply = (text) => [{ json: { chatId: r.chatId, write: false, text } }];

if (!(me && me.statusCode === 200 && me.body && me.body.id)) {
  return reply(`Everhour: nie mogę pobrać profilu (${esc(errText(me))}). Sprawdź klucz API w credentialu.`);
}
if (!(tr && tr.statusCode === 200 && Array.isArray(tr.body))) {
  return reply(`Everhour: nie mogę pobrać wpisów (${esc(errText(tr))}).`);
}

const userId = me.body.id;
const records = tr.body.filter((x) => x && x.date);
const day = records.filter((x) => x.date === r.date);
const total = day.reduce((s, x) => s + (Number(x.time) || 0), 0);
const cfgTask = String(cfg.EVERHOUR_TASK_ID ?? '').trim();
// Main task = most time in the 14 days before the day (one-off HR/meeting entries do not win)
const mainTask = (list, beforeIso) => {
  const since = DateTime.fromISO(beforeIso, { zone: ZONE }).minus({ days: 14 }).toISODate();
  const withTask = list.filter((x) => x.task && x.task.id);
  const recent = withTask.filter((x) => String(x.date) >= since);
  const totals = new Map();
  for (const x of (recent.length ? recent : withTask)) {
    const id = String(x.task.id);
    const e = totals.get(id) || { id, name: x.task.name, sec: 0, last: '' };
    e.sec += Number(x.time) || 0;
    if (String(x.date) > e.last) e.last = String(x.date);
    totals.set(id, e);
  }
  return [...totals.values()].sort((a, b) => b.sec - a.sec || b.last.localeCompare(a.last))[0] || null;
};
const auto = mainTask(records, r.date);
const taskId = cfgTask || (auto ? auto.id : '');
if (!taskId) {
  return reply('Nie wiem, na który task logować (brak wpisów z ostatnich 45 dni). Wpisz EVERHOUR_TASK_ID w node Config.');
}
const taskRec = records.find((x) => x.task && String(x.task.id) === taskId);
const taskName = taskRec ? taskRec.task.name : taskId;
const onTask = day.filter((x) => x.task && String(x.task.id) === taskId);
const onTaskSec = onTask.reduce((s, x) => s + (Number(x.time) || 0), 0);
const other = total - onTaskSec;
const desired = Number(r.seconds);
const newTaskTime = desired - other;

if (desired === total) return reply(`Za <b>${label(r.date)}</b> jest już ${fmtH(total / 3600)} h. Nic nie zmieniam.`);
if (newTaskTime <= 0) {
  return reply(`Za <b>${label(r.date)}</b> masz już ${fmtH(other / 3600)} h na innych taskach. Popraw ręcznie w Everhourze.`);
}
if (onTask.length > 1) return reply(`Za <b>${label(r.date)}</b> ten task ma kilka wpisów. Popraw ręcznie w Everhourze.`);

const existing = onTask[0] || null;
const comment = r.comment || (existing && existing.comment) || '';
const body = existing
  ? { time: newTaskTime, ...(comment ? { comment } : {}) }
  : { task: taskId, user: userId, date: r.date, time: newTaskTime, ...(comment ? { comment } : {}) };

return [{
  json: {
    chatId: r.chatId,
    write: true,
    method: existing ? 'PUT' : 'POST',
    url: existing ? `https://api.everhour.com/time/${existing.id}` : 'https://api.everhour.com/time',
    body,
    date: r.date,
    desired,
    other,
    previous: total,
    taskName,
  },
}];

// Confirmation message after the Everhour write.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
};
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const errText = (res) => {
  if (!res) return 'brak odpowiedzi';
  if (res.error) return String(res.error.message || res.error).slice(0, 200);
  const b = res.body;
  const msg = b && typeof b === 'object' ? (b.message || b.error || JSON.stringify(b)) : String(b ?? '');
  return `HTTP ${res.statusCode ?? '?'}${msg ? ': ' + msg : ''}`.slice(0, 200);
};

const plan = $('Plan time entry').first().json;
const res = $('Everhour: save time').first().json;
const ok = Boolean(res && res.statusCode >= 200 && res.statusCode < 300);
if (!ok) {
  return [{ json: { chatId: plan.chatId, ok: false, text: `Everhour odrzucił wpis za <b>${label(plan.date)}</b> (${esc(errText(res))}).` } }];
}
const saved = (res.body && Number(res.body.time)) || Number(plan.body.time);
const hours = (plan.other + saved) / 3600;
const prev = plan.previous ? ` (było ${fmtH(plan.previous / 3600)} h)` : '';
return [{
  json: {
    chatId: plan.chatId,
    ok: true,
    text: `Zapisane: <b>${fmtH(hours)} h</b> za ${label(plan.date)}${prev}, task „${esc(plan.taskName)}”.`,
    state: { date: plan.date, status: 'logged', hours, note: 'telegram' },
  },
}];

// /status: Everhour profile timezone + time tracking policy + last 7 days.
// Only selected fields are echoed (the /users/me response also contains the API key).
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
};
const fmtH = (h) => String(Math.round(h * 100) / 100).replace('.', ',');
const errText = (res) => {
  if (!res) return 'brak odpowiedzi';
  if (res.error) return String(res.error.message || res.error).slice(0, 200);
  const b = res.body;
  const msg = b && typeof b === 'object' ? (b.message || b.error || JSON.stringify(b)) : String(b ?? '');
  return `HTTP ${res.statusCode ?? '?'}${msg ? ': ' + msg : ''}`.slice(0, 200);
};
const json = (v, max) => esc(JSON.stringify(v ?? null).slice(0, max));

const r = $('Resolve action').first().json;
const me = $('Everhour: me (status)').first().json;
const tr = $('Everhour: time (status)').first().json;
const now = DateTime.now().setZone(ZONE);

if (!(me && me.statusCode === 200 && me.body && me.body.id)) {
  return [{ json: { chatId: r.chatId, text: `Everhour: nie mogę pobrać profilu (${esc(errText(me))}). Sprawdź klucz API w credentialu.` } }];
}
const u = me.body;
const warsaw = now.offset / 60;
const tz = u.timezone === undefined || u.timezone === null || u.timezone === '' ? null : Number(u.timezone);
const tzText = tz === null || Number.isNaN(tz) ? 'brak' : `UTC${tz >= 0 ? '+' : ''}${tz}`;
const teamBits = {};
if (u.team && typeof u.team === 'object') {
  for (const [k, v] of Object.entries(u.team)) if (/lock|limit|policy|workday|tracking/i.test(k)) teamBits[k] = v;
}

const lines = [
  `<b>Everhour</b>: ${esc(u.name || '')} (id ${esc(u.id)}, rola ${esc(u.role || '?')})`,
  `Strefa w profilu: ${tzText}; Warszawa teraz: UTC+${warsaw}${tz !== null && tz !== warsaw ? ' (różnica!)' : ''}`,
  `Polityka czasu (profil): <code>${json(u.timeTrackingPolicy, 500)}</code>`,
];
if (Object.keys(teamBits).length) lines.push(`Zespół: <code>${json(teamBits, 700)}</code>`);

if (tr && tr.statusCode === 200 && Array.isArray(tr.body)) {
  lines.push('', '<b>Ostatnie 7 dni</b>');
  for (let i = 6; i >= 0; i -= 1) {
    const d = now.minus({ days: i });
    const iso = d.toISODate();
    const sec = tr.body.filter((x) => x && x.date === iso).reduce((s, x) => s + (Number(x.time) || 0), 0);
    lines.push(`${label(iso)}: ${fmtH(sec / 3600)} h${sec === 0 && d.weekday <= 5 && i > 0 ? ' (brak)' : ''}`);
  }
} else {
  lines.push('', `Nie mogę pobrać wpisów (${esc(errText(tr))}).`);
}
let planned = [];
try {
  planned = $('Get pending days').all().map((i) => i.json)
    .filter((x) => x && x.status === 'day_off' && typeof x.date === 'string' && x.date >= now.toISODate())
    .map((x) => x.date).sort();
} catch (e) {
  planned = [];
}
if (planned.length) lines.push('', `<b>Zaplanowane wolne</b>: ${planned.map(label).join(', ')}`);

return [{ json: { chatId: r.chatId, text: lines.join('\n') } }];

// /tydzien and /raport. The total is Everhour's own report (GET /dashboards/users, row of this user) as-is:
// the bot never adds time up for it, it only formats seconds. Project lines come from GET /dashboards/projects
// and are shown only when they add up exactly to that total (a consistency check, not a calculation).
// Per-day lines (week only, for curiosity) come from time records and are flagged if they disagree with the report.
const ZONE = 'Europe/Warsaw';
const SHORT = ['pn', 'wt', 'śr', 'cz', 'pt', 'sb', 'nd'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = (res) => {
  if (!res) return 'brak odpowiedzi';
  if (res.error) return String(res.error.message || res.error).slice(0, 200);
  const b = res.body;
  const msg = b && typeof b === 'object' ? (b.message || b.error || JSON.stringify(b)) : String(b ?? '');
  return `HTTP ${res.statusCode ?? '?'}${msg ? ': ' + msg : ''}`.slice(0, 200);
};
const secOf = (v) => Math.round(Number(v) || 0);
const hm = (sec) => {
  const s = secOf(sec);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = s % 60;
  return `${h} h${m || r ? ` ${String(m).padStart(2, '0')} min` : ''}${r ? ` ${r} s` : ''}`;
};
// decimal hours, shown next to h/min when the total is not a whole hour; "≈" when rounded to 2 places
const dec = (sec) => {
  const v = secOf(sec) / 3600;
  const rounded = Math.round(v * 100) / 100;
  return `${Math.abs(rounded - v) > 1e-9 ? '≈' : ''}${String(rounded).replace('.', ',')} h`;
};
const both = (sec) => (secOf(sec) % 3600 ? `<b>${hm(sec)}</b> (${dec(sec)})` : `<b>${hm(sec)}</b>`);
const fd = (iso) => {
  const d = DateTime.fromISO(iso, { zone: ZONE });
  return `${d.day}.${String(d.month).padStart(2, '0')}`;
};

const r = $('Resolve action').first().json;
const me = $('Everhour: me (report)').first().json;
const users = $('Everhour: users report').first().json;
const projects = $('Everhour: projects report').first().json;
const recs = $('Everhour: time (report)').first().json;
const out = (text) => [{ json: { chatId: r.chatId, text } }];

if (!(me && me.statusCode === 200 && me.body && me.body.id)) {
  return out(`Everhour: nie mogę pobrać profilu (${esc(errText(me))}).`);
}
if (!(users && users.statusCode === 200 && Array.isArray(users.body))) {
  return out(`Everhour nie zwrócił raportu (${esc(errText(users))}). Sumy nie liczę na własną rękę.`);
}
const myId = Number(me.body.id);
const row = users.body.find((u) => u && Number(u.memberId) === myId) || null;
if (!row && users.body.length) {
  // A report came back, but not for this account: never guess a total
  const keys = Object.keys(users.body[0] || {}).slice(0, 12).join(', ');
  return out(`Raport Everhoura nie ma wiersza dla Twojego konta (id ${esc(myId)}). Pola w odpowiedzi: ${esc(keys)}. Sumy nie liczę na własną rękę.`);
}
const total = row ? secOf(row.time) : 0; // empty report = nothing tracked in the period
const month = r.reportKind === 'month';

const lines = [];
lines.push(month
  ? `<b>Raport Everhour: ${esc(r.period)}</b> (${fd(r.from)}–${fd(r.to)}${r.running ? ', miesiąc w toku' : ''})`
  : `<b>Tydzień ${esc(r.period)}</b>`);
lines.push(`Łącznie: ${both(total)}`);
if (row && secOf(row.nonBillableTime) > 0) {
  lines.push(`Billable: ${hm(row.billableTime)}, non-billable: ${hm(row.nonBillableTime)}`);
}
if (row && secOf(row.timeOffTime) > 0) {
  lines.push(`Time off w Everhourze: ${hm(row.timeOffTime)}${Number(row.timeOffDays) ? ` (${esc(row.timeOffDays)} d)` : ''}`);
}

if (projects && projects.statusCode === 200 && Array.isArray(projects.body)) {
  const list = projects.body.filter((x) => x && secOf(x.time) > 0).sort((a, b) => secOf(b.time) - secOf(a.time));
  const check = list.reduce((s, x) => s + secOf(x.time), 0);
  if (list.length && check === total) {
    if (month || list.length > 1) {
      lines.push('', '<b>Projekty</b>');
      for (const x of list) lines.push(`• ${esc(x.projectName || x.projectId)}: ${hm(x.time)}`);
    }
  } else if (list.length && month) {
    lines.push('', 'Rozbicie na projekty pominięte: raport projektów nie zgadza się z sumą.');
  }
} else if (month) {
  lines.push('', `Rozbicie na projekty niedostępne (${esc(errText(projects))}).`);
}

// Week only: per-day view from time records
if (!month) {
  if (recs && recs.statusCode === 200 && Array.isArray(recs.body)) {
    const today = DateTime.now().setZone(ZONE).toISODate();
    const inRange = recs.body.filter((x) => x && typeof x.date === 'string' && x.date >= r.from && x.date <= r.to);
    let off = new Set();
    try {
      off = new Set($('Get pending days').all().map((i) => i.json)
        .filter((x) => x && x.status === 'day_off' && typeof x.date === 'string').map((x) => x.date));
    } catch (e) {
      off = new Set();
    }
    const days = [];
    for (let d = DateTime.fromISO(r.from, { zone: ZONE }); d.toISODate() <= r.to && d.toISODate() <= today; d = d.plus({ days: 1 })) {
      const iso = d.toISODate();
      const sec = inRange.filter((x) => x.date === iso).reduce((s, x) => s + secOf(x.time), 0);
      if (d.weekday > 5 && sec === 0) continue;
      let tag = '';
      if (iso === today) tag = ' (dziś)';
      else if (sec === 0) tag = off.has(iso) ? ' (wolne)' : ' (brak)';
      days.push(`${SHORT[d.weekday - 1]} ${fd(iso)}: ${hm(sec)}${tag}`);
    }
    if (days.length) lines.push('', ...days);
    const daysTotal = inRange.reduce((s, x) => s + secOf(x.time), 0);
    if (daysTotal !== total) lines.push(`Uwaga: wpisy dzienne dają ${hm(daysTotal)}, raport Everhoura ${hm(total)}.`);
  } else {
    lines.push('', `Dni niedostępne (${esc(errText(recs))}).`);
  }
}

if (month) lines.push('', 'Źródło: raport Everhour (dashboards/users), bez przeliczeń po stronie bota.');
return out(lines.join('\n'));

// Monthly invoice reminder (for contractors billing by the hour). The invoice is due on the last workday (Mon-Fri) of the month.
// Heads-up on the day before at 9:30, then every scheduled run (9:30, 14:00, 21:30) from the due day
// until the month is marked "wystawiona" (text reply or button). State: Data table invoice_reminders.
// Config.INVOICE_REMINDERS = false switches these reminders off.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const NOM = ['styczeń', 'luty', 'marzec', 'kwiecień', 'maj', 'czerwiec', 'lipiec', 'sierpień', 'wrzesień', 'październik', 'listopad', 'grudzień'];
const GEN = ['stycznia', 'lutego', 'marca', 'kwietnia', 'maja', 'czerwca', 'lipca', 'sierpnia', 'września', 'października', 'listopada', 'grudnia'];
const label = (d) => `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
const dueDay = (y, m) => {
  let d = DateTime.fromObject({ year: y, month: m, day: 1 }, { zone: ZONE }).endOf('month').startOf('day');
  while (d.weekday > 5) d = d.minus({ days: 1 });
  return d;
};

const cfg = $('Config').first().json;
const chatId = String(cfg.TELEGRAM_CHAT_ID ?? '').trim();
if (!chatId) return [];
if (cfg.INVOICE_REMINDERS === false || String(cfg.INVOICE_REMINDERS).trim().toLowerCase() === 'false') return [];
const now = cfg.test_now
  ? DateTime.fromISO(String(cfg.test_now), { zone: ZONE })
  : DateTime.now().setZone(ZONE);
const today = now.toISODate();
const slot = now.hour < 12 ? 'morning' : (now.hour < 18 ? 'afternoon' : 'evening');
const rows = $('Get invoice rows').all().map((i) => i.json)
  .filter((r) => r && /^\d{4}-\d{2}$/.test(String(r.period || '')));
const byPeriod = new Map(rows.map((r) => [String(r.period), r]));

// Open months: already reminded and not issued, plus the current month from the day before its due day
const periods = new Set(rows.filter((r) => r.status === 'pending').map((r) => String(r.period)));
if (today >= dueDay(now.year, now.month).minus({ days: 1 }).toISODate()) periods.add(now.toFormat('yyyy-MM'));

const out = [];
for (const period of [...periods].sort()) {
  const row = byPeriod.get(period) || null;
  if (row && row.status === 'issued') continue;
  const [y, m] = period.split('-').map(Number);
  const due = dueDay(y, m);
  const dueIso = due.toISODate();
  const eveIso = due.minus({ days: 1 }).toISODate();
  const tag = `\n<code>faktura ${period}</code>`;
  let kind;
  let text;
  if (today < eveIso) continue;
  if (today === eveIso) {
    if (slot !== 'morning') continue;
    kind = 'heads-up';
    text = `Jutro (<b>${label(due)}</b>) ostatni dzień roboczy ${GEN[m - 1]}: faktura za ${NOM[m - 1]}.\nPo wystawieniu kliknij „Wystawiona” albo odpisz „wystawiona”.${tag}`;
  } else if (today === dueIso) {
    kind = 'due';
    text = slot === 'morning'
      ? `Dziś (<b>${label(due)}</b>) ostatni dzień roboczy ${GEN[m - 1]}: wystaw fakturę za ${NOM[m - 1]}.\nNajpierw wpisz dzisiejsze godziny, wtedy raport obejmie cały miesiąc.${tag}`
      : `${slot === 'evening' ? 'Termin mija dziś. ' : 'Przypominam. '}Faktura za ${NOM[m - 1]} czeka na wystawienie.${tag}`;
  } else {
    kind = 'overdue';
    text = `Faktura za ${NOM[m - 1]} nadal niewystawiona (termin: <b>${label(due)}</b>).${tag}`;
  }
  out.push({
    chatId,
    period,
    text,
    reportLabel: `Raport: ${NOM[m - 1]}`,
    reportData: `rep|${period}`,
    doneData: `inv|${period}`,
    state: { period, status: 'pending', pings: (Number(row && row.pings) || 0) + 1, note: kind },
  });
}
return out.map((json) => ({ json }));

// "wystawiona" (text, reply to a reminder, or the button): mark the invoice for a month as issued.
// Month: button / reply tag > oldest month still being reminded > current month in its last week before the due day.
const ZONE = 'Europe/Warsaw';
const DAYS = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const NOM = ['styczeń', 'luty', 'marzec', 'kwiecień', 'maj', 'czerwiec', 'lipiec', 'sierpień', 'wrzesień', 'październik', 'listopad', 'grudzień'];
const label = (d) => `${DAYS[d.weekday - 1]} ${d.day}.${String(d.month).padStart(2, '0')}`;
const dueDay = (y, m) => {
  let d = DateTime.fromObject({ year: y, month: m, day: 1 }, { zone: ZONE }).endOf('month').startOf('day');
  while (d.weekday > 5) d = d.minus({ days: 1 });
  return d;
};
const monthName = (period) => `${NOM[Number(period.slice(5)) - 1]} ${period.slice(0, 4)}`;

const p = $('Resolve action').first().json;
const now = DateTime.now().setZone(ZONE);
const today = now.toISODate();
const rows = $('Get invoice rows (reply)').all().map((i) => i.json)
  .filter((r) => r && /^\d{4}-\d{2}$/.test(String(r.period || '')));
const byPeriod = new Map(rows.map((r) => [String(r.period), r]));
const pending = rows.filter((r) => r.status === 'pending').map((r) => String(r.period)).sort();
const reply = (text) => [{ json: { chatId: p.chatId, text, write: false } }];

let period = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(p.invoicePeriod || '')) ? String(p.invoicePeriod) : '';
if (!period && pending.length) period = pending[0];
if (!period) {
  const due = dueDay(now.year, now.month);
  if (today < due.minus({ days: 7 }).toISODate()) {
    return reply(`Nie mam otwartej faktury. Najbliższy termin: <b>${label(due)}</b>, przypomnę dzień wcześniej.`);
  }
  period = now.toFormat('yyyy-MM'); // issued early, in the last week before the due day
}
const [y, m] = period.split('-').map(Number);
const row = byPeriod.get(period) || null;
if (row && row.status === 'issued') return reply(`Faktura za ${NOM[m - 1]} ${y} jest już odhaczona.`);

// Next month that still needs an invoice, counted from the current month
const issued = new Set(rows.filter((r) => r.status === 'issued').map((r) => String(r.period)));
issued.add(period);
let n = now.startOf('month');
while (issued.has(n.toFormat('yyyy-MM'))) n = n.plus({ months: 1 });
const nextDue = dueDay(n.year, n.month);
const nextLine = nextDue.toISODate() >= today
  ? ` Następna za ${NOM[n.month - 1]}, termin <b>${label(nextDue)}</b> (przypomnę dzień wcześniej).`
  : '';
const others = pending.filter((x) => x !== period);
const otherLine = others.length ? `\nNadal otwarte: ${others.map(monthName).join(', ')}.` : '';

return [{
  json: {
    chatId: p.chatId,
    write: true,
    text: `Odnotowane: faktura za ${NOM[m - 1]} wystawiona.${nextLine}${otherLine}`,
    state: { period, status: 'issued', note: 'telegram' },
  },
}];
